import {CHAPTERS,ELEMENTS,ITEMS,MOVES,SPECIES,WEATHER} from './data.js';
import {stats,moveList} from './engine.js';
import {TRIAL_CIRCUITS,TRIAL_STAGES,trialAt,trialReward} from './trial-data.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const itemIcon=id=>`<canvas width="32" height="32" data-item="${id}" aria-hidden="true"></canvas>`;
export function trialMarkup(game,floor){
 const stage=trialAt(floor),circuit=TRIAL_CIRCUITS[stage.chapter],reward=trialReward(floor),done=floor<=(game.trial||0),next=(game.trial||0)+1;
 const healthy=game.party.filter(m=>m.hp>0).length,needsRest=game.party.some(m=>m.hp<stats(m).hp||m.status);
 return `<div class="trial-hero"><div class="trial-crest" aria-hidden="true"><span>✧</span><b>${stage.endless?'∞':String(stage.chapter+1).padStart(2,'0')}</b></div><div><span class="eyebrow">${stage.endless?'八封邀请之后 · 远海回航':CHAPTERS[circuit.region].island+'的来信 · '+Math.min(game.trial||0,24)+' / 24 场已完成'}</span><h3>${stage.endless?'还有愿意再切磋的人':escape(circuit.title)}</h3><p>${stage.endless?'旧相识带着成熟的队伍回来。等级固定在 65 级，继续交换一路积累的招式与经验。':escape(circuit.summary)}</p></div></div><div class="trial-passport" aria-label="八段试航纪念">${TRIAL_CIRCUITS.map((c,i)=>{const count=Math.max(0,Math.min(3,(game.trial||0)-i*3));return `<div class="${count===3?'collected':''}"><span aria-hidden="true">${['⌁','◇','♨','≋','❄','☾','☀','✧'][i]}</span><small>${escape(c.crest)}</small><div class="trial-stamps" aria-label="完成 ${count} / 3 场">${[0,1,2].map(j=>`<i class="${j<count?'complete':''}"></i>`).join('')}</div></div>`;}).join('')}</div><section class="trial-match"><div class="trial-match-heading"><div><small>${done?'再次切磋':stage.endless?'远海挑战':'当前邀请'} · 第 ${floor} 阶${!stage.endless?' / 24':''}</small><h3>${escape(stage.title)}</h3></div><span class="trial-weather">${WEATHER[stage.weather].icon} ${WEATHER[stage.weather].name}<small>Lv.${stage.level}–${Math.min(65,stage.level+Math.min(2,stage.team.length-1))}</small></span></div><div class="trial-host"><canvas width="80" height="80" data-person="${stage.role}" aria-hidden="true"></canvas><p><small>这一场的邀请人</small><strong>${escape(stage.guest)}</strong><span>「${escape(stage.before[0][1])}」</span></p></div><div class="trial-lineup" data-size="${stage.team.length}">${stage.team.map((entry,i)=>{const species=SPECIES[entry.species],level=Math.min(65,stage.level+i%3),moves=moveList({species:entry.species,level,loadout:entry.moves});return `<article style="--trial-element:${ELEMENTS[species.element].color}"><canvas width="144" height="144" data-species="${entry.species}" aria-hidden="true"></canvas><strong>${species.name}</strong><span>${ELEMENTS[species.element].name}属性 · Lv.${level}</span><small>${entry.equip?ITEMS[entry.equip].name:'未携带护符'}</small><p>${moves.map(id=>MOVES[id].name).join(' · ')}</p></article>`;}).join('')}</div><div class="trial-tactic"><span>✦</span><div><h4>对方战术 · ${stage.tactic.name}</h4><p>${stage.tactic.desc}</p><p class="trial-advice">${escape(stage.hint)}</p></div></div></section><div class="trial-rewards"><small>${done?'已收好的首次纪念 · 重赛不重复领取':'首次完成，收好这份纪念'}</small><span>◈ 额外 ${reward.gold} 星砂</span>${Object.entries(reward.items).map(([id,n])=>`<span>${itemIcon(id)}${ITEMS[id].name} × ${n}</span>`).join('')}${reward.crest?`<span class="trial-crest-name">✧ ${escape(reward.crest)}</span>`:''}</div><div class="trial-prep"><p><strong>${healthy} / ${game.party.length} 位伙伴可以出场</strong><small>${needsRest?'有伙伴需要休息。候场营地提供免费恢复，也可以先调整招式与护符。':'伙伴们已经准备好了。比赛使用当前队伍与背包，每场结束后可以自由休息。'}</small></p><div><button id="trial-rest" class="secondary">候场营地恢复</button><button id="trial-party" class="text-button">查看队伍</button></div></div><div class="trial-start"><button class="primary" id="begin-trial" ${healthy?'':'disabled'}>${done?'再次认真切磋 →':'接下这一场邀请 →'}</button>${done&&!stage.endless?'<button class="secondary" id="trial-reread">重读赛后回声</button>':''}${floor!==next?'<button class="text-button" id="trial-next">回到下一站 →</button>':''}</div><details class="trial-schedule"><summary>查看八封邀请 · 全部 24 场试航</summary><div>${TRIAL_CIRCUITS.map((c,i)=>`<section><small>邀请 ${String(i+1).padStart(2,'0')} · ${CHAPTERS[c.region].island}</small><h4>${escape(c.title)}</h4>${TRIAL_STAGES.filter(s=>s.chapter===i).map(s=>`<button data-trial-floor="${s.floor}" ${s.floor>next?'disabled':''} class="${s.floor===floor?'selected':''}"><span>${s.floor<=game.trial?'✓':String(s.floor).padStart(2,'0')}</span><strong>${escape(s.title)}</strong><small>${s.floor<=game.trial?'可重赛':s.floor===next?'下一站':'尚未开放'}</small></button>`).join('')}</section>`).join('')}</div></details>`;
}
